  {
    "question": "A student repeating class XII to prepare for JEE typically plans a daily study schedule. Which of the following ranges is most commonly recommended for total study time per day?",
    "options": {
      "A": "2–3 hours",
      "B": "4–5 hours",
      "C": "6–8 hours",
      "D": "9–10 hours"
    },
    "correct_answer": "C",
    "explanation": "Droppers usually allocate 6–8 hours daily to cover the extensive JEE syllabus while allowing time for breaks and revision, balancing intensity and sustainability.",
    "difficulty": "Medium"
  },
  {
    "question": "Which psychological issue is most frequently reported by students who repeat a year (droppers) for competitive‑exam preparation?",
    "options": {
      "A": "Excessive confidence",
      "B": "Burnout",
      "C": "Over‑optimism",
      "D": "Indifference to results"
    },
    "correct_answer": "B",
    "explanation": "Burnout, caused by prolonged intensive study and pressure to improve scores, is a common challenge among droppers.",
    "difficulty": "Medium"
  },
  {
    "question": "Which learning technique is considered most effective for droppers aiming to retain large volumes of concepts over the repeat year?",
    "options": {
      "A": "Cramming before mock tests",
      "B": "Single‑subject intensive blocks",
      "C": "Spaced repetition with periodic revision",
      "D": "Studying only through video lectures"
    },
    "correct_answer": "C",
    "explanation": "Spaced repetition, which revisits topics at increasing intervals, enhances long‑term retention and is especially useful for the extensive JEE syllabus.",
    "difficulty": "Medium"
  },
  {
    "question": "By which month do most Class XII droppers aim to complete the entire JEE Main syllabus in their repeat year?",
    "options": {
      "A": "June",
      "B": "August",
      "C": "October",
      "D": "December"
    },
    "correct_answer": "B",
    "explanation": "Completing the syllabus by August allows ample time for revision and mock tests before the JEE Main examination held in January.",
    "difficulty": "Medium"
  },
  {
    "question": "Among the study resources listed below, which one is most heavily relied upon by droppers during their preparation for JEE Main and Advanced?",
    "options": {
      "A": "Standard school textbooks",
      "B": "Coaching institute printed notes",
      "C": "Previous‑year JEE question papers",
      "D": "General reference books on physics"
    },
    "correct_answer": "C",
    "explanation": "Analyzing previous‑year JEE papers helps droppers understand exam patterns, difficulty levels, and frequently tested concepts, making it the most utilized resource.",
    "difficulty": "Medium"
  }
]
